include!("detector.rs");
fn main(){let r=std::env::args().nth(1).unwrap();let p=std::path::Path::new(&r);let v=io::load_ops(p.join("../product-pareto-20261019/parent/ops.bin").to_str().unwrap());let cover:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(p.join("coverage.json")).unwrap()).unwrap();let mut rows=vec![];for x in cover["all_structural_cells"]["first_uncovered_regions"].as_array().unwrap().iter().take(5){let i=x[0].as_u64().unwrap() as usize;rows.push(serde_json::json!({"region":x,"context":(i-5..i+6).map(|j|serde_json::json!({"i":j,"op":format!("{:?}",v[j])})).collect::<Vec<_>>()}));}std::fs::write(p.join("gap-ops.json"),serde_json::to_string_pretty(&rows).unwrap()).unwrap();}
